struct sockaddr_in channel;   /* 地址结构：协议族、IP、端口 */
int s, sa, fd, on = 1;

memset(&channel, 0, sizeof(channel));
channel.sin_family = AF_INET;                  /* IPv4 */
channel.sin_addr.s_addr = htonl(INADDR_ANY);   /* 本机任何网卡的 IP 都接 */
channel.sin_port = htons(SERVER_PORT);         /* 服务器的固定端口，如 80 */

s = socket(PF_INET, SOCK_STREAM, IPPROTO_TCP); /* 创建端点；SOCK_STREAM = 可靠字节流 */
if (s < 0) fatal("socket failed");
setsockopt(s, SOL_SOCKET, SO_REUSEADDR, (char *) &on, sizeof(on));
if (bind(s, (struct sockaddr *) &channel, sizeof(channel)) < 0) fatal("bind failed");
if (listen(s, QUEUE_SIZE) < 0) fatal("listen failed");   /* 声明愿意接受；队列最多 QUEUE_SIZE 个 */

while (1) {
    sa = accept(s, 0, 0);                      /* 阻塞，等下一个连接；返回一个新套接字 sa */
    if (sa < 0) fatal("accept failed");
    read(sa, buf, BUF_SIZE);                   /* 在 sa 上读请求：要哪个文件 */
    fd = open(buf, O_RDONLY);                  /* 打开文件 */
    /* 课件在这里省略：把文件内容 write 回 sa */
    close(fd);                                 /* 关文件 */
    close(sa);                                 /* 关这条连接；监听用的 s 还留着 */
}

